package githubrunner

import("context";"testing";"github.com/eutelic/runnerhub/internal/core")
type fakeCatalog struct{repo Repository;group RunnerGroup;repos []Repository}
func(f fakeCatalog)ListRepositories(context.Context,core.GitHubScope)([]Repository,error){return f.repos,nil};func(f fakeCatalog)GetRepository(context.Context,string,string)(Repository,error){return f.repo,nil};func(f fakeCatalog)ListRunnerGroups(context.Context,string)([]RunnerGroup,error){return []RunnerGroup{f.group},nil};func(f fakeCatalog)GetRunnerGroup(context.Context,string,int64)(RunnerGroup,error){return f.group,nil};func(f fakeCatalog)ListRunnerGroupRepositories(context.Context,string,int64)([]Repository,error){return f.repos,nil}
func securePool()core.RunnerPool{return core.RunnerPool{Name:"secure",Scope:core.GitHubScope{Kind:core.ScopeOrganization,Owner:"acme"},Labels:[]string{"secure"},Isolation:core.IsolationContainerTrusted,MaxConcurrency:2,RunnerGroupID:7,AllowedRepositories:[]string{"acme/app"},AllowedWorkflows:[]string{"acme/app/.github/workflows/build.yml@main"}}}
func TestPoolSecurityRejectsBroaderGitHubGroup(t *testing.T){p:=securePool();f:=fakeCatalog{group:RunnerGroup{ID:7,Visibility:"selected",RestrictedToWorkflows:false},repos:[]Repository{{FullName:"acme/app",Private:true},{FullName:"acme/other",Private:true}}};got,err:=InspectPoolSecurity(context.Background(),f,p);if err!=nil{t.Fatal(err)};if got.Safe||len(got.Reasons)<2{t.Fatalf("expected unsafe posture: %+v",got)}}
func TestPoolSecurityAcceptsMatchingSelectedPolicy(t *testing.T){p:=securePool();f:=fakeCatalog{group:RunnerGroup{ID:7,Visibility:"selected",RestrictedToWorkflows:true,SelectedWorkflows:p.AllowedWorkflows},repos:[]Repository{{FullName:"acme/app",Private:true}}};got,err:=InspectPoolSecurity(context.Background(),f,p);if err!=nil{t.Fatal(err)};if !got.Safe{t.Fatalf("expected safe posture: %+v",got)}}
func TestRepositorySecurityRejectsPublic(t *testing.T){p:=core.RunnerPool{Scope:core.GitHubScope{Kind:core.ScopeRepository,Owner:"acme",Repository:"public"}};got,err:=InspectPoolSecurity(context.Background(),fakeCatalog{repo:Repository{FullName:"acme/public",Private:false}},p);if err!=nil{t.Fatal(err)};if got.Safe{t.Fatal("public repository accepted")}}
func TestRepositorySecurityRejectsWorkflowAllowlistClaim(t *testing.T){p:=core.RunnerPool{Scope:core.GitHubScope{Kind:core.ScopeRepository,Owner:"acme",Repository:"app"},AllowedWorkflows:[]string{"acme/app/.github/workflows/build.yml@main"}};got,err:=InspectPoolSecurity(context.Background(),fakeCatalog{repo:Repository{FullName:"acme/app",Private:true}},p);if err!=nil{t.Fatal(err)};if got.Safe{t.Fatal("repository-scoped workflow allowlist was presented as enforceable")}}
